update public.spell_catalog set name_ru='Огненный щит', casting_time='Действие', spell_range='На себя', area='На себя', duration='10 минут', components=array['В','С','М'], material='кусочек фосфора или светлячок', check_type='', damage='Ответный урон по атакующему в 5 футах: 2к8 огнём или холодом', effect_summary='Выбираешь тёплый или холодный щит. Тёплый даёт сопротивление холоду и отвечает огнём; холодный даёт сопротивление огню и отвечает холодом. Когда существо в 5 футах попадает по тебе рукопашной атакой, оно получает 2к8 соответствующего урона.', upcast='', notes='Не требует концентрации. Даёт яркий свет на 10 футов и тусклый ещё на 10.', author_description='Оборачиваешь себя огнём или холодом и превращаешь рукопожатие в дисциплинарную меру.', author_comment='Если враг второй раз бьёт человека, который обжигает его за каждый удар, это уже принцип.' where slug='fire-shield';
update public.spell_catalog set name_ru='Свобода передвижения', casting_time='Действие', spell_range='Касание', area='1 добровольное существо', duration='1 час', components=array['В','С','М'], material='кожаный ремешок', check_type='', damage='', effect_summary='Труднопроходимая местность не мешает движению цели. Заклинания и магические эффекты не могут уменьшить её Скорость или наложить Паралич/Опутанность. Цель получает скорость плавания, равную Скорости, и может потратить 5 футов движения, чтобы автоматически освободиться от немагических пут или Захвата.', upcast='+1 цель за каждый уровень ячейки выше 4.', notes='Не требует концентрации. Автоматическое освобождение относится только к немагическим путам и Захвату.', author_description='На час большая часть способов удержать человека перестаёт работать. Очень удобно для следопыта. Очень тревожно для тюремщика.', author_comment='Если пленник тратит пять футов движения и выходит из наручников, пора пересмотреть карьеру.' where slug='freedom-of-movement';
update public.spell_catalog set name_ru='Гигантское насекомое', casting_time='Действие', spell_range='60 футов', area='1 свободное место', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='', damage='По блоку характеристик Гигантского насекомого', effect_summary='Призываешь гигантскую многоножку, паука или осу. Существо использует отдельный блок характеристик, является союзником, делит с тобой инициативу и ходит сразу после тебя. Слушается словесных команд без действия; без приказа Уклоняется и избегает опасности.', upcast='Уровень потраченной ячейки используется как уровень заклинания в блоке характеристик существа.', notes='Исчезает при 0 HP или окончании заклинания.', author_description='Друид вызывает насекомое размером с проблему и затем удивляется, почему никто больше не хочет ночевать в лесу.', author_comment='Если это паук, не гладь. Если это друид в другой день — тоже не гладь.' where slug='giant-insect';
update public.spell_catalog set name_ru='Высшая невидимость', casting_time='Действие', spell_range='Касание', area='1 существо', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Цель получает состояние Невидимый на всё время действия.', upcast='', notes='В отличие от обычной Невидимости, эффект не заканчивается из-за атаки, урона или сотворения заклинания.', author_description='Невидимость, которая не разваливается в тот момент, когда ты решаешь действительно что-то сделать. Технологический прогресс.', author_comment='Плут теперь может воровать и драться одновременно. Именно этого миру не хватало.' where slug='greater-invisibility';
update public.spell_catalog set name_ru='Страж веры', casting_time='Действие', spell_range='30 футов', area='Большой спектральный страж; зона 10 футов', duration='8 часов', components=array['В'], material=null, check_type='Спасбросок Ловкости при первом приближении за ход или начале хода рядом', damage='20 излучением; половина при успехе; исчезает после суммарных 60 урона', effect_summary='В свободном месте появляется неуязвимый спектральный страж. Враг, впервые за ход входящий в пространство в 10 футах от него или начинающий там ход, делает спасбросок. Страж исчезает после того, как суммарно нанесёт 60 урона.', upcast='', notes='Не требует концентрации. Страж занимает своё пространство и не перемещается.', author_description='Жрец ставит на землю огромного неуязвимого охранника и уходит. Даже его вера предпочитает работать без непосредственного участия жреца.', author_comment='Шестьдесят урона и ни одной проповеди. Лучший представитель духовенства.' where slug='guardian-of-faith';
update public.spell_catalog set name_ru='Галлюцинаторная местность', casting_time='Действие', spell_range='300 футов', area='Куб 150 футов', duration='24 часа', components=array['В','С','М'], material='гриб', check_type='Распознавание: Интеллект (Расследование) против Сл спасброска заклинаний', damage='', effect_summary='Меняешь вид, звук и запах природной местности так, чтобы она казалась другой природной местностью. Можно сделать дорогу похожей на болото, обрыв — на склон, пруд — на луг и т.п.', upcast='', notes='Осязательные свойства не меняются. Постройки, снаряжение и существа не маскируются. После распознавания существо видит слабую иллюзию поверх настоящего ландшафта.', author_description='Сто пятьдесят футов земли начинают врать глазами, ушами и носом, но забывают договориться с ногами.', author_comment='Если «ровная дорога» внезапно ощущается как обрыв, доверься ногам.' where slug='hallucinatory-terrain';
update public.spell_catalog set name_ru='Ледяной шторм', casting_time='Действие', spell_range='300 футов', area='Цилиндр радиусом 20 и высотой 40 футов', duration='Мгновенно', components=array['В','С','М'], material='варежка', check_type='Спасбросок Ловкости', damage='2к10 дробящего + 4к6 холодом; половина обоих при успехе', effect_summary='На область обрушивается град. Все существа в цилиндре делают спасбросок Ловкости. Земля в области становится труднопроходимой до конца твоего следующего хода.', upcast='+1к10 дробящего урона за каждый уровень ячейки выше 4.', notes='Апкаст увеличивает только дробящий урон, не холод.', author_description='Триста футов дальности, град и холод. Магический прогноз погоды: «локально очень плохо».', author_comment='Варежка как материальный компонент — единственная разумная часть этого заклинания.' where slug='ice-storm';
update public.spell_catalog set name_ru='Поиск существа', casting_time='Действие', spell_range='На себя', area='Радиус поиска 1000 футов', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='шерсть ищейки', check_type='', damage='', effect_summary='Называешь или описываешь знакомое существо и чувствуешь направление к нему в пределах 1000 футов. Если оно движется, знаешь направление движения. Можно искать конкретное существо или ближайшее существо известного тебе вида.', upcast='', notes='Чтобы искать вид, нужно хотя бы раз видеть такое существо вблизи — в 30 футах. Не находит цель, если она изменила форму. Любая толщина свинца на прямом пути блокирует поиск.', author_description='Магический способ найти человека в пределах тысячи футов. Плуты ненавидят это заклинание по профессиональным причинам.', author_comment='Если цель превратилась в овцу, магия сдаётся. Уважительно отношусь к её границам.' where slug='locate-creature';
update public.spell_catalog set name_ru='Фантомный убийца', casting_time='Действие', spell_range='120 футов', area='1 видимое существо', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Мудрости при наложении и в конце каждого хода', damage='4к10 психического при каждом провале; половина только при первом успешном спасброске', effect_summary='Создаёшь видимый только цели образ её глубочайшего страха. При первом провале цель получает 4к10 психического урона и на время действия имеет помеху на атаки и проверки характеристик. В конце каждого хода повторяет спасбросок: провал — ещё 4к10, успех — заклинание заканчивается.', upcast='+1к10 урона за каждый уровень ячейки выше 4.', notes='Если первый спасбросок успешен, цель получает половину начального урона и заклинание сразу заканчивается.', author_description='Не показываешь человеку монстра. Показываешь именно того монстра, которого его мозг любезно хранит для особого случая.', author_comment='Самый дешёвый ингредиент здесь — собственная психика цели.' where slug='phantasmal-killer';
update public.spell_catalog set name_ru='Превращение', casting_time='Действие', spell_range='60 футов', area='1 видимое существо', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='кокон гусеницы', check_type='Спасбросок Мудрости', damage='', effect_summary='При провале цель превращается в выбранного Зверя с CR не выше CR цели или её уровня. Игровые характеристики заменяются блоком Зверя, но сохраняются мировоззрение, личность, тип существа, собственные HP и кости хитов. Цель получает временные HP, равные HP формы.', upcast='', notes='Заклинание заканчивается, когда временные HP формы заканчиваются. Цель не может говорить или колдовать, ограничена анатомией формы. Снаряжение сливается с формой и не используется.', author_description='Превращаешь человека в зверя и оставляешь ему личность. То есть теперь все плохие решения совершаются в более подходящем теле.', author_comment='Если товарищ после превращения в козла ведёт себя ровно так же, магия сработала правильно.' where slug='polymorph';
update public.spell_catalog set name_ru='Частное святилище', casting_time='Действие', spell_range='120 футов', area='Куб от 5 до 100 футов по стороне', duration='24 часа', components=array['В','С','М'], material='тонкий лист свинца', check_type='', damage='', effect_summary='Создаёшь защищённую область и выбираешь любые свойства: звук не проходит через границу; сквозь неё нельзя видеть; магические сенсоры Прорицания не входят; находящихся внутри нельзя выбирать целью Прорицания; телепортация внутрь/наружу запрещена; межпланарные перемещения блокируются.', upcast='+100 футов к максимальной стороне куба за каждый уровень ячейки выше 4.', notes='Если накладывать на одно место ежедневно 365 дней, эффект становится постоянным до рассеивания.', author_description='Сто футов приватности: никто не видит, не слышит, не телепортируется и не подглядывает магией. Наконец заклинание для людей, которые путешествовали с бардом.', author_comment='После 365 дней это уже не святилище. Это очень убедительная просьба оставить тебя в покое.' where slug='private-sanctum';
update public.spell_catalog set name_ru='Упругая сфера', casting_time='Действие', spell_range='30 футов', area='1 Большое или меньшее существо/объект', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='стеклянная сфера', check_type='Нежелающее существо: спасбросок Ловкости', damage='', effect_summary='Закрываешь цель в неуязвимой сфере. Ничто — предметы, энергия и эффекты заклинаний — не проходит через стенку ни внутрь, ни наружу. Внутри можно дышать. Существо внутри может действием катить сферу со скоростью до половины своей Скорости.', upcast='', notes='Сфера невесома и иммунна ко всему урону. Её можно переносить. Disintegrate уничтожает сферу, не причиняя вреда содержимому.', author_description='Помещаешь кого-нибудь в абсолютно защищённый пузырь. Отлично для спасения союзника и ещё лучше для временного хранения идиота.', author_comment='Если внутри волшебник, наслаждайся редкой минутой, когда его решения не влияют на окружающих.' where slug='resilient-sphere';
update public.spell_catalog set name_ru='Тайный сундук', casting_time='Действие', spell_range='Касание', area='1 особый сундук объёмом до 12 кубических футов', duration='Мгновенно; хранение продолжается, пока эффект не закончится', components=array['В','С','М'], material='сундук 3×2×2 фута из редких материалов стоимостью 5000+ зм и его Крошечная копия из тех же материалов стоимостью 50+ зм', check_type='После 60 дней: накопительный шанс 5% в конце каждого дня, что эффект закончится', damage='', effect_summary='Прячешь сундук и содержимое на Эфирном плане. Действием Магии, касаясь миниатюры, вызываешь сундук в свободное место в 5 футах; таким же способом отправляешь обратно.', upcast='', notes='Эффект заканчивается, если сотворить заклинание снова или уничтожить миниатюру. Если эффект закончился, пока большой сундук на Эфирном плане, он остаётся там и может быть найден.', author_description='Пять тысяч золотых за сундук, который можно спрятать в другом измерении. Волшебники изобрели банковскую ячейку и каким-то образом сделали её менее надёжной после шестидесяти дней.', author_comment='Если потерял миниатюру, поздравляю: твоё имущество теперь находится в очень эксклюзивном месте.' where slug='secret-chest';
update public.spell_catalog set name_ru='Форма камня', casting_time='Действие', spell_range='Касание', area='Каменный объект Среднего размера или меньше, либо участок камня до 5 футов по любому измерению', duration='Мгновенно', components=array['В','С','М'], material='мягкая глина', check_type='', damage='', effect_summary='Придаёшь камню выбранную форму: можешь сделать проход через стену до 5 футов толщиной, запечатать каменную дверь, сформировать статую, ящик или простое изделие.', upcast='', notes='Можно создать до двух петель и защёлку, но тонкие механические детали недоступны.', author_description='Каменная стена перестаёт быть препятствием и становится сырьём. Архитекторы ненавидят это заклинание.', author_comment='Если проход получился кривым, не называй это магией. Это дизайн.' where slug='stone-shape';
update public.spell_catalog set name_ru='Каменная кожа', casting_time='Действие', spell_range='Касание', area='1 добровольное существо', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='алмазная пыль стоимостью 100+ зм, расходуется', check_type='', damage='Сопротивление дробящему, колющему и рубящему урону', effect_summary='Цель получает сопротивление дробящему, колющему и рубящему урону на время действия.', upcast='', notes='Материал расходуется. Требует концентрации.', author_description='Сто золотых алмазной пыли, чтобы человек на час стал хуже воспринимать мечи. Воин обычно добивается похожего результатом многолетней практики и доспехами.', author_comment='Если концентрация падает, алмазы обратно не собираются. Магия умеет мотивировать.' where slug='stoneskin';
update public.spell_catalog set name_ru='Сфера купороса', casting_time='Действие', spell_range='150 футов', area='Сфера радиусом 20 футов', duration='Мгновенно', components=array['В','С','М'], material='капля желчи', check_type='Спасбросок Ловкости', damage='При провале: 10к4 кислотой сразу + 5к4 в конце следующего хода; при успехе — половина только начального урона', effect_summary='Кислотная сфера взрывается в выбранной точке. При провале цель получает 10к4 сразу и ещё 5к4 в конце своего следующего хода. При успехе получает только половину начального урона.', upcast='+2к4 к начальному урону за каждый уровень ячейки выше 4.', notes='Апкаст увеличивает только начальный урон. Отложенные 5к4 не растут. Исправлена опечатка исходного импорта по официальному SRD 5.2.1.', author_description='Огненный шар для людей, которым недостаточно, чтобы врагу было плохо сейчас. Кислота заботливо записывает продолжение на следующий ход.', author_comment='Если цель пережила первые 10к4, у неё есть целый ход, чтобы пожалеть об этом.' where slug='vitriolic-sphere';
update public.spell_catalog set name_ru='Стена огня', casting_time='Действие', spell_range='120 футов', area='Стена до 60×20×1 фут или кольцо диаметром до 20 футов, высотой 20 и толщиной 1 фут', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='кусочек древесного угля', check_type='При появлении: спасбросок Ловкости', damage='5к8 огнём; половина при начальном спасброске', effect_summary='Создаёшь непрозрачную стену огня. При появлении существа в её области делают спасбросок. Выбираешь одну горячую сторону: существо получает 5к8, если заканчивает ход в 10 футах от этой стороны или внутри стены, а также когда впервые за ход входит в стену. Другая сторона дополнительного жара не наносит.', upcast='+1к8 урона за каждый уровень ячейки выше 4.', notes='Направление опасной стороны выбирается при наложении. Начальный урон и последующий урон стены используют одно значение.', author_description='Шестьдесят футов стены из огня с заранее выбранной плохой стороной. Волшебник наконец применяет геометрию с понятным результатом.', author_comment='Перед применением уточни, с какой стороны союзники. Это удивительно непопулярная привычка.' where slug='wall-of-fire';